package lk.repairdesk.api.domain; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="diagnoses") @Getter @Setter @NoArgsConstructor public class Diagnosis { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="repair_request_id",unique=true) private RepairRequest repairRequest; @ManyToOne(fetch=FetchType.LAZY,optional=false) private User technician; @Column(nullable=false,length=2000) private String summary; private boolean repairable; @Column(precision=5,scale=2) private BigDecimal estimatedSuccessRate; @Column(nullable=false,updatable=false) private Instant diagnosedAt=Instant.now(); }
